mapper.select:
select id, commercial_context_type, commercial_context_id, fulfillment_type, fulfillment_id,
       beneficiary_role, beneficiary_id, service_unit, settlement_route,
       source_contract_type, source_contract_id, status, create_time
from settlement_claim
where commercial_context_type = #{commercialContextType}
  and commercial_context_id = #{commercialContextId}
  and fulfillment_type = #{fulfillmentType}
  and fulfillment_id = #{fulfillmentId}
  and beneficiary_role = #{beneficiaryRole}
  and beneficiary_id = #{beneficiaryId}
  and service_unit = #{serviceUnit}
for update
